CREATE TABLE sub13_org (employee_id INTEGER PRIMARY KEY, employee_name TEXT NOT NULL, parent_id INTEGER);
INSERT INTO sub13_org VALUES (1, 'CEO', NULL), (2, 'Asha', 1), (3, 'Bilal', 1), (4, 'Chitra', 2);
WITH RECURSIVE org_tree(employee_id, employee_name, depth) AS (
  SELECT employee_id, employee_name, 0 FROM sub13_org WHERE parent_id IS NULL
  UNION ALL
  SELECT child.employee_id, child.employee_name, parent.depth + 1
  FROM sub13_org AS child JOIN org_tree AS parent ON child.parent_id = parent.employee_id
)
SELECT employee_name, depth FROM org_tree ORDER BY depth, employee_name;

